import{_ as l,H as a,f as t,i}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"直播专场（四） | 并发问题和并发测试","description":"","frontmatter":{},"headers":[{"level":2,"title":"Part 1 并发问题","slug":"part-1-并发问题","link":"#part-1-并发问题","children":[{"level":3,"title":"Mutex","slug":"mutex","link":"#mutex","children":[]},{"level":3,"title":"Rwlock","slug":"rwlock","link":"#rwlock","children":[]},{"level":3,"title":"Condvar","slug":"condvar","link":"#condvar","children":[]},{"level":3,"title":"Once","slug":"once","link":"#once","children":[]},{"level":3,"title":"Barrier","slug":"barrier","link":"#barrier","children":[]},{"level":3,"title":"Atomic","slug":"atomic","link":"#atomic","children":[]},{"level":3,"title":"mpsc","slug":"mpsc","link":"#mpsc","children":[]},{"level":3,"title":"async","slug":"async","link":"#async","children":[]},{"level":3,"title":"竞争条件","slug":"竞争条件","link":"#竞争条件","children":[]}]},{"level":2,"title":"Part 2 并发测试","slug":"part-2-并发测试","link":"#part-2-并发测试","children":[{"level":3,"title":"单元测试 Test","slug":"单元测试-test","link":"#单元测试-test","children":[]},{"level":3,"title":"单元测试 - 异步编程","slug":"单元测试-异步编程","link":"#单元测试-异步编程","children":[]},{"level":3,"title":"并发测试的难点","slug":"并发测试的难点","link":"#并发测试的难点","children":[]},{"level":3,"title":"Loom：一个用于测试并发程序的工具","slug":"loom-一个用于测试并发程序的工具","link":"#loom-一个用于测试并发程序的工具","children":[]},{"level":3,"title":"Shuttle：一个强大的并发测试库，专为 Rust 开发者设计","slug":"shuttle-一个强大的并发测试库-专为-rust-开发者设计","link":"#shuttle-一个强大的并发测试库-专为-rust-开发者设计","children":[]},{"level":3,"title":"ThreadSanitizer (TSan) - C/C++ 的并发调试工具","slug":"threadsanitizer-tsan-c-c-的并发调试工具","link":"#threadsanitizer-tsan-c-c-的并发调试工具","children":[]}]},{"level":2,"title":"Part 3：最佳实践","slug":"part-3-最佳实践","link":"#part-3-最佳实践","children":[{"level":3,"title":"隔离测试场景","slug":"隔离测试场景","link":"#隔离测试场景","children":[]},{"level":3,"title":"增加竞争条件","slug":"增加竞争条件","link":"#增加竞争条件","children":[]},{"level":3,"title":"检查资源泄漏","slug":"检查资源泄漏","link":"#检查资源泄漏","children":[]},{"level":3,"title":"使用工具","slug":"使用工具","link":"#使用工具","children":[]},{"level":3,"title":"模拟错误","slug":"模拟错误","link":"#模拟错误","children":[]}]}],"relativePath":"Rust并发编程实战课/直播专场（四）｜并发问题和并发测试.md","filePath":"Rust并发编程实战课/直播专场（四）｜并发问题和并发测试.md","lastUpdated":1795563064000}'),r={name:"Rust并发编程实战课/直播专场（四）｜并发问题和并发测试.md"};function n(s,e,o,h,u,c){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="直播专场-四-并发问题和并发测试" tabindex="-1">直播专场（四） | 并发问题和并发测试 <a class="header-anchor" href="#直播专场-四-并发问题和并发测试" aria-label="Permalink to &quot;直播专场（四） | 并发问题和并发测试&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/1.png" alt=""></a></p><h2 id="part-1-并发问题" tabindex="-1">Part 1 并发问题 <a class="header-anchor" href="#part-1-并发问题" aria-label="Permalink to &quot;Part 1 并发问题&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/2.jpeg" alt=""></a></p><h3 id="mutex" tabindex="-1">Mutex <a class="header-anchor" href="#mutex" aria-label="Permalink to &quot;Mutex&quot;">​</a></h3><ul><li><p>重入</p></li><li><p>scope 范围太大</p></li></ul><h3 id="rwlock" tabindex="-1">Rwlock <a class="header-anchor" href="#rwlock" aria-label="Permalink to &quot;Rwlock&quot;">​</a></h3><ul><li><p>重入</p></li><li><p>读锁和写锁</p></li></ul><h3 id="condvar" tabindex="-1">Condvar <a class="header-anchor" href="#condvar" aria-label="Permalink to &quot;Condvar&quot;">​</a></h3><ul><li><p>消费者在生产者通知之后进入等待，可能错过通知</p></li><li><p>虚假唤醒导致条件未满足</p></li></ul><h3 id="once" tabindex="-1">Once <a class="header-anchor" href="#once" aria-label="Permalink to &quot;Once&quot;">​</a></h3><ul><li>初始化逻辑中再次调用</li></ul><h3 id="barrier" tabindex="-1">Barrier <a class="header-anchor" href="#barrier" aria-label="Permalink to &quot;Barrier&quot;">​</a></h3><ul><li>启动的参与者不够</li></ul><h3 id="atomic" tabindex="-1">Atomic <a class="header-anchor" href="#atomic" aria-label="Permalink to &quot;Atomic&quot;">​</a></h3><ul><li><p>错误的内存序</p></li><li><p>误以为的原子操作</p></li></ul><h3 id="mpsc" tabindex="-1">mpsc <a class="header-anchor" href="#mpsc" aria-label="Permalink to &quot;mpsc&quot;">​</a></h3><ul><li>没有生产者，消费者无限等待</li></ul><h3 id="async" tabindex="-1">async <a class="header-anchor" href="#async" aria-label="Permalink to &quot;async&quot;">​</a></h3><ul><li>阻塞线程</li></ul><h3 id="竞争条件" tabindex="-1">竞争条件 <a class="header-anchor" href="#竞争条件" aria-label="Permalink to &quot;竞争条件&quot;">​</a></h3><ul><li>不确定的结果</li></ul><h2 id="part-2-并发测试" tabindex="-1">Part 2 并发测试 <a class="header-anchor" href="#part-2-并发测试" aria-label="Permalink to &quot;Part 2 并发测试&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/3.jpeg" alt=""></a></p><h3 id="单元测试-test" tabindex="-1">单元测试 Test <a class="header-anchor" href="#单元测试-test" aria-label="Permalink to &quot;单元测试 Test&quot;">​</a></h3><ul><li><p>使用 std:🧵:spawn 创建多个线程，模拟并发访问。</p></li><li><p>使用 std::sync 原语（如 Mutex、RwLock、Atomic）或通道（mpsc）测试共享状态。</p></li><li><p>增加线程竞争（例如通过 thread::yield_now 或短暂睡眠）以暴露潜在问题。</p></li></ul><h3 id="单元测试-异步编程" tabindex="-1">单元测试 - 异步编程 <a class="header-anchor" href="#单元测试-异步编程" aria-label="Permalink to &quot;单元测试 - 异步编程&quot;">​</a></h3><ul><li><p>使用 #[tokio::test] 或 #[async_std::test] 运行异步测试。</p></li><li><p>模拟高并发任务，检查资源竞争或死锁。</p></li><li><p>使用 tokio::time::timeout 测试异步任务的超时行为。</p></li></ul><h3 id="并发测试的难点" tabindex="-1">并发测试的难点 <a class="header-anchor" href="#并发测试的难点" aria-label="Permalink to &quot;并发测试的难点&quot;">​</a></h3><ul><li><p>非确定性：线程调度和异步任务执行顺序不可预测，问题可能在特定条件下触发。</p></li><li><p>可重现性：并发 bug 难以稳定重现。</p></li><li><p>覆盖率：需要测试多种线程交错和错误场景。</p></li></ul><h3 id="loom-一个用于测试并发程序的工具" tabindex="-1">Loom：一个用于测试并发程序的工具 <a class="header-anchor" href="#loom-一个用于测试并发程序的工具" aria-label="Permalink to &quot;Loom：一个用于测试并发程序的工具&quot;">​</a></h3><p>在高层次上，它会多次运行测试，根据 C11 内存模型中有效执行的定义，对每个测试的可能并发执行进行排列组合。然后，它使用状态缩减技术来避免可能执行的数量的组合爆炸。</p><ul><li><p>write 获取写锁</p></li><li><p>read 获得读锁</p></li><li><p>Arc&lt;​RwLock&gt;: 多线程访问</p></li><li><p>Guard 自动释放</p></li></ul><h3 id="shuttle-一个强大的并发测试库-专为-rust-开发者设计" tabindex="-1">Shuttle：一个强大的并发测试库，专为 Rust 开发者设计 <a class="header-anchor" href="#shuttle-一个强大的并发测试库-专为-rust-开发者设计" aria-label="Permalink to &quot;Shuttle：一个强大的并发测试库，专为 Rust 开发者设计&quot;">​</a></h3><p>它通过模拟不同的执行顺序来测试并发代码， 帮助开发者发现潜在的竞态条件、死锁和其他并发问题。</p><ul><li><p>自动探索不同的执行顺序，无需手动编写复杂的测试场景</p></li><li><p>支持测试多线程、异步代码和无锁数据结构</p></li><li><p>可以检测数据竞争、死锁和其他并发错误</p></li><li><p>提供详细的错误报告，帮助定位和修复问题</p></li><li><p>与 Rust 的测试框架无缝集成，易于在现有项目中使用</p></li></ul><h3 id="threadsanitizer-tsan-c-c-的并发调试工具" tabindex="-1">ThreadSanitizer (TSan) - C/C++ 的并发调试工具 <a class="header-anchor" href="#threadsanitizer-tsan-c-c-的并发调试工具" aria-label="Permalink to &quot;ThreadSanitizer (TSan) - C/C++ 的并发调试工具&quot;">​</a></h3><p>RUSTFLAGS=“-Z sanitizer=thread” cargo run/test，检测数据竞争</p><p><a href="https://github.com/japaric/rust-san" target="_blank" rel="noreferrer">https://github.com/japaric/rust-san</a></p><p><a href="https://rustc-dev-guide.rust-lang.org/sanitizers.html" target="_blank" rel="noreferrer">https://rustc-dev-guide.rust-lang.org/sanitizers.html</a></p><h2 id="part-3-最佳实践" tabindex="-1">Part 3：最佳实践 <a class="header-anchor" href="#part-3-最佳实践" aria-label="Permalink to &quot;Part 3：最佳实践&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/4.jpeg" alt=""></a></p><h3 id="隔离测试场景" tabindex="-1">隔离测试场景 <a class="header-anchor" href="#隔离测试场景" aria-label="Permalink to &quot;隔离测试场景&quot;">​</a></h3><ul><li><p>为每个并发原语或逻辑编写单独的测试用例。</p></li><li><p>测试边缘情况，如高并发、分支、空状态或错误路径。</p></li></ul><h3 id="增加竞争条件" tabindex="-1">增加竞争条件 <a class="header-anchor" href="#增加竞争条件" aria-label="Permalink to &quot;增加竞争条件&quot;">​</a></h3><ul><li><p>使用 thread::yield_now、thread::sleep 或随机延迟触发线程切换。</p></li><li><p>在异步测试中使用 tokio::task::yield_now。</p></li></ul><h3 id="检查资源泄漏" tabindex="-1">检查资源泄漏 <a class="header-anchor" href="#检查资源泄漏" aria-label="Permalink to &quot;检查资源泄漏&quot;">​</a></h3><ul><li><p>使用 Arc::strong_count 检查引用计数是否正确释放。</p></li><li><p>监控内存使用，检测线程池或异步任务泄漏。</p></li><li><p>监控 CPU 占用，检查是否 CPU 异常持续占用</p></li></ul><h3 id="使用工具" tabindex="-1">使用工具 <a class="header-anchor" href="#使用工具" aria-label="Permalink to &quot;使用工具&quot;">​</a></h3><ul><li><p>Loom：检测自定义原语或复杂逻辑的并发 bug。</p></li><li><p>Shuttle: 测试各种边缘场景</p></li><li><p>TSan/Valgrind：检测数据竞争。</p></li><li><p>Cargo Fuzz：模糊测试并发代码的输入。</p></li></ul><h3 id="模拟错误" tabindex="-1">模拟错误 <a class="header-anchor" href="#模拟错误" aria-label="Permalink to &quot;模拟错误&quot;">​</a></h3><ul><li><p>测试 panic 场景，使用 std::panic::catch_unwind。</p></li><li><p>检查 Mutex 毒化或通道关闭后的行为。</p></li></ul>',52)])])}const E=l(r,[["render",n]]);export{d as __pageData,E as default};
